function validarCorreo(t){return/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(t)}function soloLetras(t){return/^[a-zA-ZáéíóúÁÉÍÓÚñÑ\s]+$/.test(t)&&t.trim().length>0}function validarLongitud(t,e){const n=t.toString().trim();return/^\d+$/.test(n)&&n.length<=e}function calcularEdad(t){const e=new Date(t),n=new Date(e.getTime()+Math.abs(6e4*e.getTimezoneOffset())),r=new Date;let a=r.getFullYear()-n.getFullYear();const o=r.getMonth()-n.getMonth();return(o<0||0===o&&r.getDate()<n.getDate())&&a--,a}function esMayorDeEdad(t){return calcularEdad(t)>=18}function validarPassword(t){return/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,}$/.test(t)}function formatearTelefonoMX(t){const e=t.toString().replace(/\D/g,"");return 10===e.length?e.replace(/(\d{3})(\d{3})(\d{2})(\d{2})/,"$1 $2 $3 $4"):t}function limpiarTexto(t){return t.trim().replace(/\s+/g," ")}